scripts/start.sh:48:  --no-seed       leave the guest book empty. By default a guest book that has
scripts/start.sh:49:                  no entries is filled from golden-set/seed/ once the application
scripts/start.sh:76:no_seed=0
scripts/start.sh:91:        --no-seed) no_seed=1 ;;
scripts/start.sh:106:#: Fill the guest book from `golden-set/seed/` once the application answers.
scripts/start.sh:110:# one hands the terminal to Vite. Seeding before the poll would be seeding
scripts/start.sh:113:# `seed.sh` carries the judgement -- it refuses production and skips a guest book
scripts/start.sh:121:seed_when_up() {
scripts/start.sh:134:                "$REPO_ROOT/scripts/seed.sh" --base-url "$base_url" >/dev/null 2>&1 ||
scripts/start.sh:135:                    warn "the seed corpus did not go in; the application is running"
scripts/start.sh:167:    # `seed.sh` needs uv. Letting it fail and warning would keep the promise in
scripts/start.sh:170:    # need. So the seeding is skipped and SAID to be skipped: an empty guest book
scripts/start.sh:172:    if [ "$no_seed" -eq 0 ]; then
scripts/start.sh:174:            "$REPO_ROOT/scripts/seed.sh" --base-url "http://127.0.0.1:${APP_PORT}/api" ||
scripts/start.sh:175:                warn "the seed corpus did not go in; the application is running"
scripts/start.sh:177:            info "not seeded: the seeder needs uv, which this mode does not ask for"
scripts/start.sh:178:            info "to fill it later: ./scripts/seed.sh (needs uv), or add entries on the screen"
scripts/start.sh:248:    [ "$no_seed" -eq 0 ] && seed_when_up "http://127.0.0.1:${APP_PORT}/api"
scripts/start.sh:257:# vite.config.ts proxies to it. The seeder talks to the API directly, so it wants
scripts/start.sh:259:[ "$no_seed" -eq 0 ] && seed_when_up "http://127.0.0.1:8000/api"
{
  "story": "welcome",
  "demonstrates": "What a freshly created environment opens with -- a preview, a fresh clone, a stage nobody has written in yet. Entries chosen to be LOOKED AT rather than asserted about: they carry the round-trip properties that make a screen worth judging (characters outside ASCII, a message with line breaks, a short one beside a long one) and no value anywhere near a published limit, because a signature padded to eighty characters is a screen nobody can read.",
  "entries": [
    {
      "author": "The template",
      "message": "Welcome. This guest book was filled when the environment was created, so there is something on the screen to judge. Every entry here arrived the way a guest's entry arrives -- posted through the API, and subject to the same rules."
    },
    {
      "author": "Zoë Ångström",
      "message": "café · naïve · Ærø · 日本語 · Ωμέγα — the characters above ASCII are here on purpose: if they survive as far as your eyes, they survived the database, the contract and the browser."
    },
    {
      "author": "Clara Multiline",
      "message": "The first line of an entry.\nA second line, after a newline.\n\nA fourth, after a blank one — whitespace INSIDE a message is left alone; only the edges are trimmed."
    },
    {
      "author": "Brian Example",
      "message": "A short one, to show what the list looks like when the entries are not all the same length."
    },
    {
      "author": "Ada Placeholder",
      "message": "Newest first, so this one is at the top until somebody writes the next. Delete the guest book and this file goes with it -- the example is an example."
    }
  ]
}

